b.constraint('proof_projection_separation',['requirement_declaration'],'Keep subject-artifact, verifier-artifact, verifier-execution and semantic-interpretation projections distinct. Test-relation, test-source and test-execution are compatibility spellings for generic proof roles, never GTL Product test policy.',[(0,33,33)])
b.constraint('requirement_conformance_rejections',['requirement_declaration'],'Fail closed for malformed declarations, duplicate stable requirement/relation/span ids, dangling references, term relation/span refs, relation endpoints and proof-relation requirement ids, invalid spans, unresolved callable/vector refs, unknown relation kinds, open payloads and authority-smuggling fields.',[(0,35,35),(0,51,51)])
