b.constraint('rule_evaluator_gate_split',['rule'],'Rule states required truth, Evaluator checks/attests convergence, and gate blocks/allows continuation. Engines may enforce declared protocol, while business, merge, ranking and approval semantics stay outside interpreter unless supplied by declarations and resolved implementations.',[(6,19,25)],exceptions=['Explicit declarations plus resolved implementations may supply underlying domain semantics.'])
