b.constraint('subwork_ownership_chain',['bounded_subwork'],'GTL owns declared topology/scope/bounds/schema; validator checks static relations; HoG traverses admitted declaration; selected implementation realizes native leaf effect; ABG owns lifecycle, transport-contract admission, runtime facts and replay. Bounded work requires no Product-local shadow runtime logic in GTL.',[(15,17,23)])
b.constraint('synthesis_contract_conservation',['deferred_synthesis'],'Every produced Graph/callable satisfies declared interface/obligations and enters only through lawful outer-contract-preserving substitution/refinement. Preserve structural provenance identifying refined boundary and applied graph/callable. Materializing a callable or companion bundle preserves published callable identity and declared materialization truth.',[(18,16,20),(18,26,30)])
b.latitude('synthesis_declaration_latitude',['deferred_synthesis'],['Expose tags, hints, governance hooks, opaque config and capability requirements without hidden strategy.','Expose multiple lawful candidates or one lawful boundary without deciding a choice.','Declare trigger visibility through evaluators/hooks; engines execute declared protocol.'],['Engine invention of trigger semantics.','Treating declared candidates as automatically chosen.'],[(18,22,28)])
